contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: send an amount to Deposit and check balances/update
    function run(uint amount) public payable {
        // ensure this contract has enough balance if sending Ether
        require(address(this).balance >= amount);

        // read balance of this contract in c before the operation
        uint before = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        // call Deposit on c sending `amount` wei
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        // If the call did not revert then the recorded balance must have increased by amount
        // and the contract's Ether balance must also have increased by amount.
        // If it reverted then neither observable should have increased (they remain equal to before).
        assert(reverted
            ? (after == before && cBalAfter == cBalBefore)
            : (after == before + amount && cBalAfter == cBalBefore + amount)
        );
    }

    receive() external payable {}
}

