contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint collectAmount) public payable {
        // We will first deposit some funds into c from this contract so Collect can potentially succeed.
        // Ensure this contract has enough balance to deposit an arbitrary amount: require caller funded the test
        require(address(this).balance >= msg.value);

        // Use some deposit amount equal to msg.value (could be zero)
        uint depositAmount = msg.value;

        // Record before-values
        uint beforeBalanceOfThis = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // If depositAmount>0 send Ether to c via Deposit() using the explicit call
        if (depositAmount > 0) {
            // call Deposit payable
            c.Deposit{value: depositAmount}();
        }

        // Read mid-values after deposit
        uint midBalanceOfThis = c.balances(address(this));
        uint midContractEth = address(c).balance;

        // Now attempt Collect(collectAmount) and catch revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterBalanceOfThis = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // General rule to assert:
        // - If Collect reverted then balances and contract ETH remain unchanged from mid-values.
        // - If Collect succeeded then the recorded balance of this decreased by exactly collectAmount,
        //   and contract ETH decreased by at least collectAmount (external call may fail but code reverts in that case,
        //   so successful Collect must transfer the ETH out, reducing contract balance by at least collectAmount).
        assert(
            (reverted && afterBalanceOfThis == midBalanceOfThis && afterContractEth == midContractEth)
            ||
            (!reverted && midBalanceOfThis >= collectAmount && afterBalanceOfThis + collectAmount == midBalanceOfThis && midContractEth >= afterContractEth && midContractEth - afterContractEth >= collectAmount)
        );
    }
    receive() external payable { }
}

