    // params:
    // dep1: first deposit amount
    // dep2: second deposit amount
    function run(uint dep1, uint dep2) public payable {
        // require we have enough ETH to fund both deposits
        require(address(this).balance >= dep1 + dep2);

        // read initial recorded balance for this contract as seen in c
        uint before = c.balances(address(this));
        uint cbal_before = address(c).balance;

        // perform first deposit
        c.Deposit{value: dep1}();

        // record after first deposit
        uint mid = c.balances(address(this));
        uint cbal_mid = address(c).balance;

        // perform second deposit via receive fallback (send Ether with no data)
        (bool ok, ) = address(c).call{value: dep2}("");
        // ok may be false only if the call reverted; in that case the contract state should be unchanged

        // final observed values
        uint after = c.balances(address(this));
        uint cbal_after = address(c).balance;

        // General rule:
        // 1) Deposits never decrease the recorded balance for this caller: mid >= before and after >= mid.
        // 2) If a particular deposit call succeeded (we observe the contract balance increase accordingly)
        //    then the recorded balance increased by at most that amount and the contract balance increased by that amount.
        // 3) If a particular deposit call reverted (observed as no change in address(c).balance) then recorded balance did not change.
        // We express these using only public getters and balances.

        // Check relation after first deposit: either contract balance increased by dep1 and recorded increased by exactly dep1,
        // or contract balance unchanged and recorded unchanged.
        bool firstSuc = (cbal_mid == cbal_before + dep1);
        bool firstFail = (cbal_mid == cbal_before);

        bool cond1 = (firstSuc && mid == before + dep1) || (firstFail && mid == before);

        // Check relation after second deposit (using ok inference via contract balance change):
        bool secondSuc = (cbal_after == cbal_mid + dep2);
        bool secondFail = (cbal_after == cbal_mid);

        bool cond2 = (secondSuc && after == mid + dep2) || (secondFail && after == mid);

        // Monotonicity: deposits do not decrease recorded balances
        bool monotonic = mid >= before && after >= mid;

        assert(cond1 && cond2 && monotonic);
    }

    receive() external payable {}
}

