        uint finalRecorded = c.balances(address(this));
        uint finalCbal = address(c).balance;

        // General rule:
        // If Collect reverted then both recorded balance and contract balance remain equal to after-values.
        // If Collect succeeded then both recorded balance and contract balance decreased by exactly collectAmt,
        // but only if afterRecorded >= c.MinSum() and afterRecorded >= collectAmt (those are required by Collect logic).

